import {cellsOf} from './treasure-solver-model.mjs';
const data=await fetch(new URL('./treasure-data/stages.json',import.meta.url)).then(r=>r.json());
const $=s=>document.querySelector(s),key='milkroad-treasure-solver-v1';let state={stage:1,set:0,empty:[],found:[]},history=[],worker,selected=0,draft;
try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&data.stages[saved.stage-1]?.sets[saved.set]&&Array.isArray(saved.empty)&&Array.isArray(saved.found))state=saved;}catch{}
const stage=()=>data.stages[state.stage-1],set=()=>stage().sets[state.set];
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{}}
function action(fn){history.push(structuredClone(state));fn();save();render();}
function render(){worker?.terminate();const n=stage().rows;$('#stage-number').value=state.stage;$('#treasure-set').innerHTML=stage().sets.map((s,i)=>`<option value="${i}">${s.treasures.map(t=>`${t.count} × ${t.name}`).join(' · ')}</option>`).join('');$('#treasure-set').value=state.set;$('#undo').disabled=!history.length;$('#previous').disabled=state.stage===1;$('#next').disabled=state.stage===data.stages.length;
 const board=$('#board');board.style.setProperty('--n',n);const size=n*11;board.style.cssText+=`width:calc(${size}% - 5px);height:calc(${size}% - 10px);left:${(100-size)/2}%;top:${(100-size)/2}%;`;board.replaceChildren();const covered=new Set(state.found.flatMap(p=>cellsOf(p,n)));for(let i=0;i<n*n;i++){const b=document.createElement('button');b.className='tile'+(state.empty.includes(i)||state.found.some(p=>p.revealed===i)?' empty':'');b.type='button';b.dataset.cell=i;b.setAttribute('aria-label',`Row ${Math.floor(i/n)+1}, column ${i%n+1}${covered.has(i)?', confirmed treasure':state.empty.includes(i)?', empty':''}`);if(covered.has(i))b.innerHTML='<img class="mark" src="treasure-data/check.png" alt="Confirmed treasure">';b.onclick=()=>openTile(i);board.append(b);}
 for(const p of state.found){const t=set().treasures.find(t=>t.id===p.id),box=document.createElement('div'),img=document.createElement('img');box.className='placed';box.style.cssText=`left:${p.x/n*100}%;top:${p.y/n*100}%;width:${p.w/n*100}%;height:${p.h/n*100}%;`;const reveal=p.revealed??p.y*n+p.x,rx=reveal%n-p.x,ry=Math.floor(reveal/n)-p.y;box.style.clipPath=`inset(${ry/p.h*100}% ${(p.w-rx-1)/p.w*100}% ${(p.h-ry-1)/p.h*100}% ${rx/p.w*100}%)`;img.src=t.image;img.alt='';img.style.cssText=p.w!==t.width?`position:absolute;width:${p.h/p.w*100}%;height:${p.w/p.h*100}%;left:50%;top:50%;transform:translate(-50%,-50%) rotate(90deg)`: 'width:100%;height:100%';box.append(img);board.append(box);}
 $('#status').textContent='Calculating tile chances…';worker=new Worker(new URL('./treasure-solver-worker.mjs',import.meta.url),{type:'module'});worker.onmessage=({data:r})=>{if(r.error){$('#status').textContent=r.error;return;}const available=r.probabilities.filter((_,i)=>!covered.has(i)&&!state.empty.includes(i)),max=Math.max(0,...available);r.probabilities.forEach((p,i)=>{const b=board.querySelector(`[data-cell="${i}"]`);if(covered.has(i)||state.empty.includes(i))return;b.setAttribute('aria-label',b.getAttribute('aria-label')+`, estimated chance ${Math.round(p*100)} percent`);if(max>0&&Math.round(max*100)===Math.round(p*100))b.insertAdjacentHTML('beforeend',`<span class="recommend"><img src="treasure-data/thumb.png" alt="Recommended"><strong>${Math.round(p*100)}%</strong></span>`);});$('#status').textContent=max===0?'All treasures have been located.':`Estimated chances · ${Math.round(r.effective).toLocaleString()} effective sampled layouts${r.effective<500?' · Low confidence: retry for more samples.':''}`;};worker.onerror=()=>$('#status').textContent='Calculation failed. Reload to retry.';worker.postMessage({set:set(),n,empty:state.empty,found:state.found});}
function openTile(i){selected=i;draft=null;$('#tile-title').textContent=`Row ${Math.floor(i/stage().rows)+1}, column ${i%stage().rows+1}`;$('#placement').hidden=true;$('#treasures').replaceChildren();for(const t of set().treasures){if(state.found.filter(p=>p.id===t.id).length>=t.count)continue;const b=document.createElement('button');const icon=document.createElement('img'),caption=document.createElement('span');icon.src=t.image;icon.alt='';caption.textContent=t.name;b.append(icon,caption);b.onclick=()=>choose(t,false);$('#treasures').append(b);}$('#tile-dialog').showModal();}
function choose(t,rotated){const w=rotated?t.height:t.width,h=rotated?t.width:t.height;$('#placement').hidden=false;$('#rotate').hidden=!t.rotate||t.width===t.height;$('#rotate').onclick=()=>choose(t,!rotated);const parts=$('#parts');parts.style.gridTemplateColumns=`repeat(${w},1fr)`;parts.replaceChildren();for(let dy=0;dy<h;dy++)for(let dx=0;dx<w;dx++){const b=document.createElement('button');b.setAttribute('aria-label',`Treasure part row ${dy+1}, column ${dx+1}`);const art=document.createElement('img');art.src=t.image;art.alt='';art.style.cssText=rotated?`position:absolute;width:${h*100}%;height:${w*100}%;left:${(w/2-dx)*100}%;top:${(h/2-dy)*100}%;transform:translate(-50%,-50%) rotate(90deg)`:`position:absolute;width:${w*100}%;height:${h*100}%;left:${-dx*100}%;top:${-dy*100}%;`;b.append(art);b.onclick=()=>{const n=stage().rows,p={id:t.id,x:selected%n-dx,y:Math.floor(selected/n)-dy,w,h,revealed:selected};const cells=cellsOf(p,n),used=new Set([...state.empty,...state.found.flatMap(f=>cellsOf(f,n))]);if(p.x<0||p.y<0||p.x+w>n||p.y+h>n||cells.some(c=>used.has(c))){$('#placement-note').textContent='That placement overlaps an empty tile, another treasure, or the edge.';return;}action(()=>state.found.push(p));$('#tile-dialog').close();};parts.append(b);}$('#placement-note').textContent='Select the part you uncovered. The whole footprint will be confirmed.';}
$('#mark-empty').onclick=()=>{action(()=>{state.found=state.found.filter(p=>!cellsOf(p,stage().rows).includes(selected));if(!state.empty.includes(selected))state.empty.push(selected);});$('#tile-dialog').close();};$('#mark-unknown').onclick=()=>{action(()=>{state.empty=state.empty.filter(c=>c!==selected);state.found=state.found.filter(p=>!cellsOf(p,stage().rows).includes(selected));});$('#tile-dialog').close();};$('#close-dialog').onclick=()=>$('#tile-dialog').close();
function changeStage(value){action(()=>state={stage:Math.max(1,Math.min(data.stages.length,value)),set:0,empty:[],found:[]});}
$('#previous').onclick=()=>changeStage(state.stage-1);$('#next').onclick=()=>changeStage(state.stage+1);$('#stage-number').onchange=e=>changeStage(Number(e.target.value));$('#treasure-set').onchange=e=>action(()=>{state.set=Number(e.target.value);state.empty=[];state.found=[];});$('#clear').onclick=()=>action(()=>{state.empty=[];state.found=[];});$('#undo').onclick=()=>{if(history.length){state=history.pop();save();render();}};$('#retry').onclick=render;render();
